import{_ as a,o,c as t,a3 as i}from"./chunks/framework.uTHcANy5.js";const p=JSON.parse('{"title":"Who Mosaic is for","description":"","frontmatter":{},"headers":[],"relativePath":"welcome/who.md","filePath":"welcome/who.md"}'),s={name:"welcome/who.md"};function r(n,e,l,d,c,m){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="who-mosaic-is-for" tabindex="-1">Who Mosaic is for <a class="header-anchor" href="#who-mosaic-is-for" aria-label="Permalink to &quot;Who Mosaic is for&quot;">​</a></h1><p>Mosaic is for anyone whose data is <strong>made by several parties and composed into one picture</strong>, and who needs to keep track of which part came from whom.</p><h2 id="building-and-infrastructure-teams" tabindex="-1">Building and infrastructure teams <a class="header-anchor" href="#building-and-infrastructure-teams" aria-label="Permalink to &quot;Building and infrastructure teams&quot;">​</a></h2><p>A building is designed as separate models: structural, architectural and services, often per building and per discipline, each owned and published by a different team. Mosaic keeps each one as its own file and federates them through a coordination model that imports them all, with no merged copy to fall out of date.</p><ul><li>IFC models convert in, keeping their <code>GlobalId</code>s as node ids, so a re-export from the authoring tool doesn&#39;t break references into it. See <a href="/mosaic/dist/docs/tools/ifc">Importing IFC</a>.</li><li>Types are first-class. Geometry, materials, classification and cost can live on a type and reach every instance through <code>core::inherit</code>.</li><li>Every change carries its author, time and reason.</li></ul><p>See <a href="/mosaic/dist/docs/welcome/minimal-example">A minimal example</a> and the <a href="/mosaic/dist/docs/examples/#s1">S1 example</a>.</p><h2 id="_3d-and-geometry-pipelines" tabindex="-1">3D and geometry pipelines <a class="header-anchor" href="#_3d-and-geometry-pipelines" aria-label="Permalink to &quot;3D and geometry pipelines&quot;">​</a></h2><p>For teams moving assets between tools, Mosaic is a layer <em>above</em> glTF. A model converts in (the Damaged Helmet round-trips with identical geometry, materials and textures), scenes place it by reference instead of copying it, and composing writes a standard <code>.glb</code> that any viewer opens. See <a href="/mosaic/dist/docs/tools/gltf">Importing glTF</a> and <a href="/mosaic/dist/docs/tools/compose">Composing a GLB</a>.</p><h2 id="developers-of-tools-and-platforms" tabindex="-1">Developers of tools and platforms <a class="header-anchor" href="#developers-of-tools-and-platforms" aria-label="Permalink to &quot;Developers of tools and platforms&quot;">​</a></h2><p>If you are building something that reads, writes or serves this kind of data:</p><ul><li>The <a href="/mosaic/dist/docs/standard/">standard</a> is two machine-readable documents, a JSON Schema and an OpenAPI description, so you can implement it in any language.</li><li>Component types are JSON Schemas, so your own data fits in without changing the format, and <a href="/mosaic/dist/docs/tools/codegen">code generation</a> gives you typed classes for it.</li><li>The <a href="/mosaic/dist/docs/sdk/">reference implementation</a> in TypeScript, the <code>mosaic</code> CLI and the viewer are there to build on, or to test your implementation against.</li></ul><h2 id="not-a-good-fit-yet" tabindex="-1">Not a good fit (yet) <a class="header-anchor" href="#not-a-good-fit-yet" aria-label="Permalink to &quot;Not a good fit (yet)&quot;">​</a></h2><ul><li><strong>Production use.</strong> Mosaic is pre-1.0, and both the schema and the tooling will change.</li><li><strong>A single author working in a single tool.</strong> If one tool owns the whole picture, its own format is likely simpler.</li><li><strong>Real-time collaboration.</strong> Mosaic layers published edits. It does not merge keystrokes live.</li></ul>',13)])])}const f=a(s,[["render",r]]);export{p as __pageData,f as default};
